fn job(budget: usize, leases: usize) -> RasterJob {
    RasterJob::new(ChargeLedger::new(&owner(), budget, leases).unwrap()).unwrap()
}
fn output(job: &mut RasterJob) -> JobBuffer<u8> {
    job.buffer(RasterPool::Output, usize::MAX, &mut Run).unwrap()
