struct CancelAt {
    checkpoints: usize,
    charges: usize,
}
impl WorkControl for CancelAt {
    fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
        if self.checkpoints == 0 {
            return Err(Stop::Canceled);
        }
        self.checkpoints -= 1;
        Ok(())
    }
    fn charge(&mut self, _: WorkKind, _: u64) -> std::result::Result<(), Stop> {
        if self.charges == 0 {
            return Err(Stop::Canceled);
        }
        self.charges -= 1;
        Ok(())
    }
}
