        boundary_pixel_range(
            x1.min(x2) - px - eps,
            x1.max(x2) + px + eps,
            view.viewport.width,
        ),
        boundary_pixel_range(
            y1.min(y2) - py - eps,
            y1.max(y2) + py + eps,
            view.viewport.height,
        ),
    ) {
        (Some((x_first, x_last)), Some((y_first, y_last))) => PixelBounds {
            x_first,
            x_last,
            y_first,
            y_last,
            visible: true,
        },
        _ => PixelBounds::default(),
    }
}

