static const uint8_t W8_PREVIEW_SHA256[CC_SHA256_DIGEST_LENGTH] = {
    0x9eU, 0x0aU, 0xf1U, 0xa5U, 0xd0U, 0x14U, 0xafU, 0x71U,
    0x0fU, 0xabU, 0xb3U, 0x9fU, 0xa1U, 0x52U, 0x73U, 0x3fU,
