    if (error == SVG_SHAPE_ERROR_NONE) svg_shape_document_destroy(&document);
    svg_shape_alloc_tracking_stop(&stats);
    check(stats.live_bytes == 0U, "(d) live bytes zero after failure");
    free(source);
