pub fn build_fill_row(
    cache: &mut FillCache,
    view: SceneView<'_>,
    shape: ShapeId,
    y: u32,
    map: ViewMapping,
    rows: &RowBuffers,
    _resources: &dyn KernelResources,
    control: &mut dyn WorkControl,
) -> Result<FillRowWork> {
    let si = shape.index();
    if !eligible_shapes(cache, si)
        || y >= view.viewport.height
        || !map.scale_y.is_finite()
        || map.scale_y <= 0.0
