            view.viewport.view_y + ((y as f64 + SAMPLE_Y[sample]) - map.offset_y) / map.scale_y;
        let (visits, work, _) = build_intervals(
            view,
            si,
            sy,
            &rows.active_edges[first..end],
            cache,
            sample,
            control,
