fn mark_job_box(
    job: &mut RasterJob,
    scratch: &JobRasterScratch,
    b: PixelBounds,
    width: u32,
    control: &mut dyn WorkControl,
) -> Result<()> {
    if !b.visible {
        return Ok(());
    }
    let len = job.slice(scratch.boundary_bits)?.len();
    for y in b.y_first..=b.y_last {
        for x in b.x_first..=b.x_last {
